const tabId = 480038480;
const pageFareCheck = await browserjs(tabId, () => {
  const fareMatches = [];
  const text = document.body.innerText;
  const regex = /fare/gi;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const start = Math.max(0, match.index - 50);
    const end = Math.min(text.length, match.index + 50);
    fareMatches.push(text.slice(start, end).replace(/\n/g, ' '));
  }

  const fareLinks = Array.from(document.querySelectorAll("a"))
    .filter(a => a.href.toLowerCase().includes("fare") || a.textContent.toLowerCase().includes("fare"))
    .map(a => ({ text: a.textContent.trim().replace(/\s+/g, ' '), href: a.href }));

  return { fareMatches: fareMatches.slice(0, 10), fareLinks };
});
